const R = 6371000;               // radio medio de la Tierra en metros
const rad = (g) => (g * Math.PI) / 180;
function distancia(a, b) {       // fórmula de haversine: distancia sobre una esfera
  const dLat = rad(b.lat - a.lat), dLng = rad(b.lng - a.lng);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
}
const base = { lat: -34.6, lng: -58.4 }; // punto inventado, cerca de Buenos Aires
for (const d of [1, 0.1, 0.01, 0.001, 0.0001, 0.00001, 0.000001]) {
  const norte = distancia(base, { lat: base.lat + d, lng: base.lng });
  const este = distancia(base, { lat: base.lat, lng: base.lng + d });
  const f = (m) => (m >= 1000 ? (m / 1000).toFixed(2) + " km" : m >= 1 ? m.toFixed(1) + " m" : (m * 100).toFixed(0) + " cm");
  console.log(String(d).padEnd(9), "norte-sur:", f(norte).padStart(10), "  este-oeste:", f(este).padStart(10));
}

